const row = $input.item.json;
const trigger = $('Webhook - Sign Contract Public').first().json;
const body = trigger.body || {};
const forwardedFor = (trigger.headers && trigger.headers['x-forwarded-for']) || '';
const signatureIp = forwardedFor.split(',')[0].trim() || null;
if (!row.id) throw new Error('Contract not found.');

const signatureName = (body.signature_name || '').toString().trim();
const signatureEmail = (body.signature_email || '').toString().trim();
const signatureDate = (body.signature_date || '').toString().trim();
const signatureData = (body.signature_data || '').toString();
const fieldValues = body.field_values && typeof body.field_values === 'object' ? body.field_values : {};

if (row.status !== 'signed') {
  if (!signatureName) throw new Error('Full name is required.');
  if (!signatureEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(signatureEmail)) throw new Error('A valid email is required.');
  if (!signatureDate) throw new Error('Date is required.');
  if (!signatureData) throw new Error('A signature is required.');
}

return [{
  json: {
    contractId: row.id,
    opportunityId: row.opportunity_id,
    contractSignedStageId: row.contract_signed_stage_id,
    alreadySigned: row.status === 'signed',
    signatureName, signatureEmail, signatureDate, signatureData, fieldValues, signatureIp,
    publicToken: row.public_token,
    email: row.email,
    firstName: row.first_name,
    dealName: row.deal_name,
    ownerName: row.owner_name,
    ownerEmail: row.owner_email,
  },
}];

const v = $('Validate & Prepare Sign').item.json;
const base = 'http://localhost:5173';
const link = `${base}/documents/contract/${v.publicToken}`;
return [{
  json: {
    to: v.signatureEmail || v.email,
    subject: 'Your contract has been signed',
    body: `Hi ${v.firstName || v.signatureName || 'there'},\n\nThanks for signing! Your signed contract is confirmed. You can view or download your copy anytime here:\n${link}\n`,
  },
}];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const qs = $('Webhook - Get Contracts').first().json.query || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const opportunityIdRaw = parseInt(qs.opportunity_id, 10);
const opportunityId = Number.isInteger(opportunityIdRaw) ? opportunityIdRaw : null;
return [{ json: { opportunityId, requesterId: requester.id, requesterRole: requester.role } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const opportunity = $input.item.json;
const requester = $('Look Up Requester (Save)').first().json;
const body = $('Webhook - Save Contract').first().json.body || {};

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!opportunity || opportunity.assigned_user === undefined) throw new Error('Deal not found.');
if (requester.role !== 'admin' && opportunity.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

const id = body.id ? parseInt(body.id, 10) : null;
const opportunityId = parseInt(body.opportunity_id, 10);
const title = (body.title || '').toString().trim();
const contentHtml = (body.content_html || '').toString();
const totalAmount = body.total_amount !== undefined && body.total_amount !== null && body.total_amount !== '' ? Number(body.total_amount) : 0;
const emailSubject = (body.email_subject || '').toString().trim() || 'Your contract is ready to sign';
const emailBody = (body.email_body || '').toString().trim() || 'Hi {{first_name}}, please review and sign your contract here: {{contract_link}}';

if (!Number.isInteger(opportunityId)) throw new Error('"opportunity_id" is required.');
if (!title) throw new Error('"title" is required.');
if (!contentHtml.trim()) throw new Error('Contract content is required.');
if (!Number.isFinite(totalAmount) || totalAmount < 0) throw new Error('"total_amount" must be 0 or more.');

return [{
  json: { id, opportunityId, title, contentHtml, totalAmount, emailSubject, emailBody, pipelineId: opportunity.pipeline_id, stageId: opportunity.stage_id, requesterId: requester.id },
}];

const validated = $('Validate & Payload (Save)').first().json;
const flow = $input.item.json;
return [{ json: { ...validated, flowId: flow.id } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.contract_id, 10);
if (!Number.isInteger(contractId)) throw new Error('"contract_id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), contractId } }];

const row = $input.item.json;
const requester = $('Look Up Requester (Send)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.contract_id) throw new Error('Contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');
if (!row.email) throw new Error("This deal's contact has no email address on file.");

const base = 'http://localhost:5173';
const link = `${base}/documents/contract/${row.public_token}`;

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*contract_link\s*}}/gi, link);
}

return [{ json: { contractId: row.contract_id, to: row.email, subject: fill(row.email_subject), body: fill(row.email_body) } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.id, 10);
if (!Number.isInteger(contractId)) throw new Error('"id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), contractId } }];

const row = $input.item.json;
const requester = $('Look Up Requester (Archive)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { contractId: row.id } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.id, 10);
if (!Number.isInteger(contractId)) throw new Error('"id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), contractId } }];

const row = $input.item.json;
const requester = $('Look Up Requester (Delete)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { contractId: row.id } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) throw new Error('Contract not found.');
return [{ json: { success: true } }];

// Notifies the deal owner (assigned rep) that their client just signed —
// separate from Send Signed Confirmation Email above, which goes to the
// client. Runs regardless of whether the client confirmation succeeded, so
// an owner still gets notified even if that earlier Gmail call failed.
const v = $('Validate & Prepare Sign').item.json;
return [{
  json: {
    to: v.ownerEmail,
    subject: `Deal ${v.dealName || ''} has been signed!`.trim(),
    body: `Hi ${v.ownerName || 'there'},\n\n${v.signatureName} just signed the contract for ${v.dealName || 'this deal'}. The deal has moved to Contract Signed.\n`,
  },
}];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
const qs = $('Webhook - Get Contract Signed').first().json.query || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const contractId = parseInt(qs.id, 10);
if (!Number.isInteger(contractId)) throw new Error('A valid id query parameter is required.');
return [{ json: { contractId, requesterId: requester.id, requesterRole: requester.role } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.contract_id, 10);
if (!Number.isInteger(contractId)) throw new Error('"contract_id" must be an integer.');
const to = (body.to || '').toString().trim();
const subject = (body.subject || '').toString().trim();
const message = (body.body || '').toString().trim();
if (!to || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) throw new Error('A valid "to" email is required.');
if (!subject) throw new Error('Subject is required.');
if (!message) throw new Error('Message body is required.');

return [{ json: { requesterId: parseInt(match[1], 10), contractId, to, subject, message } }];

const row = $input.item.json;
const requester = $('Look Up Requester (Send Signed)').first().json;
const payload = $('Parse Token & Payload (Send Signed)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.contract_id) throw new Error('Signed contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { to: payload.to, subject: payload.subject, body: payload.message } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.contract_id, 10);
if (!Number.isInteger(contractId)) throw new Error('"contract_id" must be an integer.');

return [{ json: { requesterId: parseInt(match[1], 10), contractId } }];

const row = $input.item.json;
const requester = $('Look Up Requester (PDF)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');

return [{ json: { title: row.title, publicToken: row.public_token, proposalToken: row.proposal_token || null } }];

const bin = $input.item.binary && $input.item.binary.data;
if (!bin) throw new Error('No PDF data received.');
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const title = $('Validate & Prepare (PDF)').first().json.title;
return [{ json: { success: true, title, pdfBase64: buffer.toString('base64') } }];
